import{_ as a,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const s=JSON.parse('{"title":"观照","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-观照.md","filePath":"50-概念资料/dict-观照.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-观照.md"};function i(d,t,h,u,c,n){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="观照" tabindex="-1">观照 <a class="header-anchor" href="#观照" aria-label="Permalink to &quot;观照&quot;">​</a></h1><blockquote><p>传统：佛家 | 道家对应：内观 | 通用：觉察</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>观照是了空居士修行体系中最核心的实操方法——以清净心观察自己的念头、情绪、身体感受，不评判、不跟随、不压制。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;与我修炼方法非常简单：与人为善，观察自己的念头。正确的肯定，错误的否定，解不开的诚心请教别人。&quot;</p></blockquote><blockquote><p>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</p></blockquote><blockquote><p>&quot;不怕念起，只怕觉迟。走神了，知道走神就不走神。&quot;</p></blockquote><blockquote><p>&quot;行住坐卧，绵绵若存——随时保持一种轻轻返观身体的状态。&quot;</p></blockquote><h2 id="观照的三个层次" tabindex="-1">观照的三个层次 <a class="header-anchor" href="#观照的三个层次" aria-label="Permalink to &quot;观照的三个层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>对象</th><th>方法</th></tr></thead><tbody><tr><td>初级</td><td>念头</td><td>知道自己在想什么</td></tr><tr><td>中级</td><td>情绪</td><td>知道自己在愤怒/悲伤/恐惧</td></tr><tr><td>高级</td><td>身体</td><td>轻轻返观全身，似守非守</td></tr></tbody></table><h2 id="关键心法" tabindex="-1">关键心法 <a class="header-anchor" href="#关键心法" aria-label="Permalink to &quot;关键心法&quot;">​</a></h2><ul><li>观照不是分析——不是追究&quot;为什么会有这个念头&quot;</li><li>观照不是压制——不是&quot;不能有这个念头&quot;</li><li>观照就是<strong>知道</strong>——像一盏灯，只照亮，不评论</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-止观">止观</a> — 了空居士的观照相当于止观合一</li><li><a href="/50-概念资料/dict-清净心">清净心</a> — 观照到极致就是清净心</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 观照的具体应用</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 观照身体是命功的基础</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>每天花几分钟安安静静观察自己的念头</li><li>日常生活中时不时&quot;退一步&quot;看看自己在做什么</li><li>情绪来了先深呼吸，然后轻轻观察它</li></ul>',19)])])}const b=a(r,[["render",i]]);export{s as __pageData,b as default};
